//miller-rabin primality test
bool isprime(int n, int k) {
    if (n <= 1 || n == 4) return false;
    if (n <= 3) return true;
    int d = n - 1;
    while (d % 2 == 0) {
        d /= 2;
    }
    for (int I = 0; I < k; i++) {
        int a = 2 + rand() % (n - 4);
        int x = power(a, d, n);
        if (x == 1 || x == n - 1) continue;
        bool flag = false;
        while (d != n - 1) {
            x = (x * x) % n;
            d *= 2;
            if (x == 1) return false;
            if (x == n - 1) {
                flag = true;
                break;
            }
        }
        if (!flag) return false;
    }
    return true;
}

