int generateprime(int bits) {
    int k = 5; //number of iterations for miller-rabin primality test
    int p = 0;
    while (true) {
        p = rand() % (1<<(bits-1)) + (1<<(bits-2));
        if (isprime(p, k))
            break;
    }
    return p;
}

